import { unstable_cache, revalidateTag } from 'next/cache';
import { getAllProducts } from '@/lib/db';

// Cache the product data with a tag for invalidation
const getCachedProducts = unstable_cache(
  async () => {
    return await getAllProducts();
  },
  ['all-products'],
  {
    tags: ['products']
  }
);

export default async function AdminCatalogPage() {
  const products = await getCachedProducts();

  async function syncCatalog() {
    'use server';

    // Trigger background revalidation
    revalidateTag('products');
  }

  return (
    <div style={{ padding: '2rem', maxWidth: '1200px', margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
        <h1 style={{ fontSize: '2rem', fontWeight: 'bold' }}>Product Catalog</h1>

        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              backgroundColor: '#0070f3',
              color: 'white',
              border: 'none',
              borderRadius: '0.25rem',
              cursor: 'pointer',
              fontSize: '1rem'
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <div style={{
        border: '1px solid #eaeaea',
        borderRadius: '0.5rem',
        overflow: 'hidden'
      }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr style={{ backgroundColor: '#fafafa', borderBottom: '1px solid #eaeaea' }}>
              <th style={{ padding: '1rem', textAlign: 'left', fontWeight: '600' }}>ID</th>
              <th style={{ padding: '1rem', textAlign: 'left', fontWeight: '600' }}>Name</th>
              <th style={{ padding: '1rem', textAlign: 'right', fontWeight: '600' }}>Price</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product, index) => (
              <tr
                key={product.id}
                style={{
                  borderBottom: index < products.length - 1 ? '1px solid #eaeaea' : 'none'
                }}
              >
                <td style={{ padding: '1rem' }}>{product.id}</td>
                <td style={{ padding: '1rem' }}>{product.name}</td>
                <td style={{ padding: '1rem', textAlign: 'right' }}>${product.price}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <p style={{ marginTop: '1rem', color: '#666', fontSize: '0.875rem' }}>
        Product data is cached for fast browsing. Click "Sync latest catalog" to refresh from upstream systems.
      </p>
    </div>
  );
}

