import { unstable_cache } from 'next/cache';
import { getAllProducts } from '@/lib/db';

// Use the same cache tag to share cached data
const getCachedProducts = unstable_cache(
  async () => {
    return await getAllProducts();
  },
  ['all-products-dashboard'],
  {
    tags: ['products']
  }
);

export default async function AdminDashboardPage() {
  const products = await getCachedProducts();

  return (
    <div style={{ padding: '2rem', maxWidth: '1200px', margin: '0 auto' }}>
      <h1 style={{ fontSize: '2rem', fontWeight: 'bold', marginBottom: '1rem' }}>Dashboard</h1>

      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
        gap: '1rem',
        marginBottom: '2rem'
      }}>
        <div style={{
          padding: '1.5rem',
          border: '1px solid #eaeaea',
          borderRadius: '0.5rem',
          backgroundColor: '#fafafa'
        }}>
          <div style={{ fontSize: '2rem', fontWeight: 'bold' }}>{products.length}</div>
          <div style={{ color: '#666', fontSize: '0.875rem' }}>Total Products</div>
        </div>

        <div style={{
          padding: '1.5rem',
          border: '1px solid #eaeaea',
          borderRadius: '0.5rem',
          backgroundColor: '#fafafa'
        }}>
          <div style={{ fontSize: '2rem', fontWeight: 'bold' }}>
            ${products.reduce((sum, p) => sum + p.price, 0)}
          </div>
          <div style={{ color: '#666', fontSize: '0.875rem' }}>Total Value</div>
        </div>
      </div>

      <div>
        <h2 style={{ fontSize: '1.25rem', fontWeight: 'bold', marginBottom: '1rem' }}>
          Recent Products
        </h2>
        <ul style={{ listStyle: 'none', padding: 0 }}>
          {products.slice(0, 3).map((product) => (
            <li
              key={product.id}
              style={{
                padding: '0.75rem',
                borderBottom: '1px solid #eaeaea'
              }}
            >
              {product.name} - ${product.price}
            </li>
          ))}
        </ul>
      </div>

      <p style={{ marginTop: '1rem', color: '#666', fontSize: '0.875rem' }}>
        This view shares the same cached product data. When catalog is synced, this page will also update.
      </p>

      <div style={{ marginTop: '2rem' }}>
        <a
          href="/admin/catalog"
          style={{
            color: '#0070f3',
            textDecoration: 'underline'
          }}
        >
          Go to Product Catalog →
        </a>
      </div>
    </div>
  );
}

